    def calculate_loan_payment(principal: float, annual_interest_rate: float, loan_term_years: int) -> float:
        if annual_interest_rate <= 0:
            # Handle the case where annual_interest_rate is 0 separately to avoid division by zero or incorrect formula use
            # If rate is 0, monthly payment is simply principal / number_of_payments
            if annual_interest_rate == 0:
                number_of_payments = loan_term_years * 12
                if number_of_payments == 0:
                    raise ValueError("Loan term cannot be zero years when interest rate is zero.")
                return principal / number_of_payments
            else:
                raise ValueError("Annual interest rate must be greater than or equal to 0 for a valid loan calculation.")

        monthly_interest_rate = annual_interest_rate / 12
        number_of_payments = loan_term_years * 12
        monthly_payment = (principal * monthly_interest_rate) / (1 - (1 + monthly_interest_rate) ** -number_of_payments)

        return monthly_payment

    principal_amount = 30000.0
    annual_rate = 0.06
    term_years = 5

    monthly_payment = calculate_loan_payment(principal_amount, annual_rate, term_years)
    return round(monthly_payment, 2)

